package com.bn.aliagent.evaluation.dataset;
import com.bn.aliagent.evaluation.anonymization.*; import com.bn.aliagent.evaluation.candidate.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*;
public final class EvaluationDatasetService implements EvaluationDatasetReader { private final CandidateRepository candidates;private final PublicDatasetAnonymizer publicAnonymizer;private final EvaluationDatasetRepository repository;private final Map<UUID,EvaluationDataset> drafts=new LinkedHashMap<>();private final Map<UUID,PublishedDatasetVersion> published=new LinkedHashMap<>();public EvaluationDatasetService(CandidateRepository c,PublicDatasetAnonymizer p){candidates=c;publicAnonymizer=p;repository=c instanceof EvaluationDatasetRepository value?value:null;}public EvaluationDataset createDraft(String tenant,String name){if(repository!=null)return repository.createDraft(tenant,name);var d=new EvaluationDataset(UUID.randomUUID(),tenant,name,false,new ArrayList<>());drafts.put(d.id(),d);return d;}public void addCandidate(String tenant,UUID id,UUID candidateId){if(repository!=null){repository.addCandidate(tenant,id,candidateId);return;}var d=requireDraft(tenant,id);var c=candidates.require(tenant,candidateId);if(c.status()!=CandidateStatus.ACCEPTED)throw new IllegalStateException("只允许已接受候选加入评测集");d.candidateIds().add(candidateId);}public PublishedDatasetVersion publish(String tenant,UUID id,boolean shared,DatasetShareAuthorization auth){if(repository!=null)return repository.publish(tenant,id,shared,auth);var d=requireDraft(tenant,id);var samples=new ArrayList<DatasetSampleSnapshot>();for(var candidateId:d.candidateIds()){var c=candidates.require(tenant,candidateId);String input=c.body().orElseThrow(()->new IllegalStateException("候选正文已删除"));if(shared){var r=publicAnonymizer.anonymize(Map.of("input",input),tenant,auth);if(r.status()!=AnonymizationStatus.SAFE)throw new IllegalStateException("公共匿名化失败");input=r.canonicalJson();}samples.add(new DatasetSampleSnapshot(c.id(),input,c.expected(),c.labels(),Set.of(),Set.of(),Map.of(),Set.of(),Set.of(),Set.of(),false,Map.of(),Set.of()));}String digest=digest(samples);var v=new PublishedDatasetVersion(UUID.randomUUID(),tenant,d.id(),1,digest,shared,samples);published.put(v.id(),v);drafts.put(d.id(),new EvaluationDataset(d.id(),d.tenantId(),d.name(),true,List.copyOf(d.candidateIds())));return v;}public PublishedDatasetVersion requirePublished(String tenant,UUID id){if(repository!=null)return repository.requirePublished(tenant,id);var v=published.get(id);if(v==null)throw new IllegalArgumentException("评测集版本不存在");if(!v.tenantId().equals(tenant))throw new SecurityException("跨租户访问被拒绝");return v;}private EvaluationDataset requireDraft(String tenant,UUID id){var d=drafts.get(id);if(d==null)throw new IllegalArgumentException("评测集不存在");if(!d.tenantId().equals(tenant))throw new SecurityException("跨租户访问被拒绝");if(d.published())throw new IllegalStateException("已发布草稿不可编辑");return d;}private static String digest(List<DatasetSampleSnapshot> samples){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(samples.toString().getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
